mapper.select:
select cs.id as id, cs.scene_name as sceneName, cs.scene_description as sceneDescription, cs.synonyms as synonyms, cs.status as status, sd1.item_text as statusName, concat(su.firstname, '-', su.employee_id) as operator, cs.create_time as createTime, cs.update_time as updateTime from ins_car_scene cs left join sys_users su on su.id = cs.update_by left join (select sdi.item_text,sdi.item_value from ins_dict sd left join ins_dict_item sdi on sdi.dict_id = sd.id where sd.dict_code = 'enable_type' ) sd1 on sd1.item_value = cs.status where 1 = 1
and cs.id = #{model.id}
and cs.scene_name like concat('%', #{model.sceneName}, '%')
and cs.scene_description like concat('%', #{model.sceneDescription}, '%')
and cs.synonyms like concat('%', #{model.synonyms}, '%')
and cs.status = #{model.status}
and cs.id in
#{item}
and cs.update_by = #{model.operator}
order by ${model.order}
order by cs.create_time desc

select distinct su.id as id, concat(ifnull(su.firstname, ''), '-', ifnull(su.employee_id, '')) as userName from sys_credentials sc left join sys_users su on sc.user_id = su.id where sc.app_id = #{appId}
and sc.user_id in
#{userId}
order by su.firstname asc, su.employee_id asc

select category_id as categoryId, count(1) as sceneCount from ins_car_scene where category_id in
#{item}
group by category_id
